  var player=new Audio(recordedUrl);clipPlayer=playback=player;
  player.onplaying=function(){if(clipPlayer===player)clipState('playing')};
  player.onpause=function(){if(clipPlayer===player&&!player.ended)clipState('paused')};
  player.onended=function(){if(clipPlayer===player){clipPlayer=null;playback=null;clipState('idle')}};
  player.onerror=function(){if(clipPlayer===player){stopPlayback();toast('无法播放这段录音')}};
