function layoutMapPieces(nodes){
 var links=[];
 for(var i=0;i<nodes.length;i++)for(var j=i+1;j<nodes.length;j++){
  var a=nodes[i],b=nodes[j],dx=b.bx-a.bx,dy=b.by-a.by,dist=Math.hypot(dx,dy)||1,ux=dx/dist,uy=dy/dist;
  if(Math.abs(dx)<(a.w+b.w)/2+130&&Math.abs(dy)<(a.h+b.h)/2+130){
   var ar=Math.min(a.w/(2*Math.max(.001,Math.abs(ux))),a.h/(2*Math.max(.001,Math.abs(uy))));
   var br=Math.min(b.w/(2*Math.max(.001,Math.abs(ux))),b.h/(2*Math.max(.001,Math.abs(uy))));
   links.push({a:a,b:b,min:dist+ar*(a.scale-1)+br*(b.scale-1)});
  }
 }
 for(var step=0;step<100;step++)links.forEach(function(l){var dx=l.b.x-l.a.x,dy=l.b.y-l.a.y,dist=Math.hypot(dx,dy)||1,extra=l.min-dist;if(extra>.01){var push=extra*.51;l.a.x-=dx/dist*push;l.a.y-=dy/dist*push;l.b.x+=dx/dist*push;l.b.y+=dy/dist*push}});
 return nodes;
}
function renderMap(){
 var map=document.getElementById('regionPuzzleMap');if(!map)return;var world=map.querySelector('.map-puzzle-world');if(!world)return;
 var nodes=Object.keys(mapTileLayout).map(function(id){var p=mapTileLayout[id],d=dialects.find(function(v){return v.id===id}),count=mapRecordsFor(d).length;return{id:id,w:p.w,h:p.h,bx:p.x+p.w/2,by:p.y+p.h/2,x:p.x+p.w/2,y:p.y+p.h/2,scale:1+count*.05,count:count}});
 layoutMapPieces(nodes);var left=Infinity,top=Infinity,right=-Infinity,bottom=-Infinity;
 nodes.forEach(function(n){left=Math.min(left,n.x-n.w*n.scale/2);top=Math.min(top,n.y-n.h*n.scale/2);right=Math.max(right,n.x+n.w*n.scale/2);bottom=Math.max(bottom,n.y+n.h*n.scale/2)});
 var fit=Math.min((map.clientWidth-24)/(right-left),(map.clientHeight-24)/(bottom-top));if(!isFinite(fit)||fit<=0)return;
 world.style.transform='translate('+(map.clientWidth/2-(left+right)/2*fit)+'px,'+(map.clientHeight/2-(top+bottom)/2*fit)+'px) scale('+fit+')';
 nodes.forEach(function(n){var tile=world.querySelector('[data-id="'+n.id+'"]');tile.style.width=n.w+'px';tile.style.height=n.h+'px';tile.style.transform='translate('+(n.x-n.w/2)+'px,'+(n.y-n.h/2)+'px) scale('+n.scale+')';tile.setAttribute('aria-label',mapTileLayout[n.id].name+'，'+n.count+' 段乡音');tile.classList.toggle('has-voices',n.count>0)});
}
